// Some portions generated by Codex
package org.eclipse.rdf4j.query.algebra;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

class SliceTest {

	@Test
	void signatureSeparatesLimitAndOffset() {
		assertThat(new Slice(new SingletonSet(), 5, 100).getSignature()).isEqualTo("Slice (limit=100, offset=5)");
	}

	@Test
	void signatureSeparatesLimitAndOffsetAtNumericBoundaries() {
		assertThat(new Slice(new SingletonSet(), Long.MAX_VALUE, 0).getSignature())
				.isEqualTo("Slice (limit=0, offset=" + Long.MAX_VALUE + ")");
	}

	@Test
	void signatureOmitsUnsetBounds() {
		assertThat(new Slice(new SingletonSet(), -1, 100).getSignature()).isEqualTo("Slice (limit=100)");
		assertThat(new Slice(new SingletonSet(), 0, 100).getSignature()).isEqualTo("Slice (limit=100)");
		assertThat(new Slice(new SingletonSet(), 5, -1).getSignature()).isEqualTo("Slice (offset=5)");
		assertThat(new Slice(new SingletonSet()).getSignature()).isEqualTo("Slice ()");
	}
}
